    private static final Map<String, VSoundType> MAPPING = new HashMap<>();
    private static final List<VSoundType> ALL = new ArrayList<>();

    static {
        try {
            for (Field constantField : VSoundType.class.getFields()) {
                if (!Modifier.isStatic(constantField.getModifiers())) continue;

                VSoundType soundType = (VSoundType) constantField.get(null);
                MAPPING.put(constantField.getName(), soundType);
                MAPPING.put(soundType.key, soundType);
                ALL.add(soundType);
            }
        } catch (Exception failed) {
            throw new Error(failed);
        }
    }

    public static VSoundType valueOf(String constantName) {
        return MAPPING.get(constantName);
    }

    public static VSoundType[] values() {
        return ALL.toArray(new VSoundType[0]);
    }

